    using Structures.World;

    /// <summary>
    /// A first approximation of every map's region volumes, from the two things the client does
    /// know about them. Each REGION_LABEL marker on the map screen (generated.client.uimapmarker)
    /// names a region and gives the point its label is drawn at: that becomes a circle there,
    /// surface only, with a radius of half the distance to the nearest other label on the map
    /// (60-200 m). Each region with its own minimap (generated.client.gamecontextuiradarinfo)
    /// gives the rectangle that minimap covers: that becomes a box, underground-only where the
    /// walkable floor inside it is mostly under the terrain (the caverns), anywhere otherwise.
    /// The radar offsets are in minimap image space, so z is negated. Generated from
    /// Rasa\world\regions.csv and the floor analysis of the client meshes.
    /// </summary>
    public class MapRegionPreloader : PreloaderBase, IPreloader
    {
        public void Preload(MigrationBuilder migrationBuilder)
        {
            Insert(migrationBuilder, MapRegionEntry.TableName, typeof(MapRegionEntry));
        }

